func loadRateMap(rt *RateTable, raw json.RawMessage, global bool) error {
  var m map[string]json.RawMessage
  if err := json.Unmarshal(raw, &m); err != nil {
    return err
  }
  for currency, raw2 := range m {
    if currency == "USD" {
      continue
    }
    r, err := parseRateRaw(raw2)
    if err != nil {
      return err
    }
    if global {
      rt.global[currency] = r
    } else {
      if rt.byDate["global"] == nil {
        rt.byDate["global"] = map[string]float64{}
      }
      rt.byDate["global"][currency] = r
    }
  }
  return nil
}

func loadRates(path string) (*RateTable, error) {
  data, err := os.ReadFile(path)
  if err != nil {
    return nil, err
  }
  var top map[string]json.RawMessage
  if err := json.Unmarshal(data, &top); err != nil {
    return nil, err
  }
  rt := newRateTable()
  for _, key := range []string{"by_date", "byDate"} {
    if raw, ok := top[key]; ok {
      var dates map[string]json.RawMessage
      if err := json.Unmarshal(raw, &dates); err != nil {
        return nil, err
      }
      for date, raw2 := range dates {
        var currencies map[string]json.RawMessage
        if err := json.Unmarshal(raw2, &currencies); err != nil {
          return nil, err
        }
        for currency, raw3 := range currencies {
          if currency == "USD" {
            continue
          }
          r, err := parseRateRaw(raw3)
          if err != nil {
            return nil, err
          }
          if rt.byDate[date] == nil {
            rt.byDate[date] = map[string]float64{}
          }
          rt.byDate[date][currency] = r
        }
      }
      delete(top, key)
    }
  }
  for _, key := range []string{"global", "Global"} {
    if raw, ok := top[key]; ok {
      if err := loadRateMap(rt, raw, true); err != nil {
        return nil, err
      }
      delete(top, key)
    }
  }
  if raw, ok := top["rates"]; ok {
    if err := loadRateMap(rt, raw, true); err != nil {
      return nil, err
    }
    delete(top, "rates")
  }
  for currency, raw := range top {
    if currency == "USD" {
      continue
    }
    var f float64
    if err := json.Unmarshal(raw, &f); err == nil {
      if !isFinite(f) {
        return nil, fmt.Errorf("bad rate for %s", currency)
      }
      rt.global[currency] = f
      continue
    }
    var dates map[string]json.RawMessage
    if err := json.Unmarshal(raw, &dates); err == nil {
      for date, raw2 := range dates {
        r, err := parseRateRaw(raw2)
        if err != nil {
          return nil, err
        }
        if rt.byDate[date] == nil {
          rt.byDate[date] = map[string]float64{}
        }
        rt.byDate[date][currency] = r
      }
      continue
    }
    return nil, fmt.Errorf("bad rate for %s", currency)
  }
  return rt, nil
}

