  }
  return t.UTC()
}

func calendarDayDiff(rateDate, eventDate string) int {
  r := dayEpoch(rateDate)
  e := dayEpoch(eventDate)
  if r.IsZero() || e.IsZero() {
    return 0
  }
  return int(r.Sub(e) / (24 * time.Hour))
}

func absInt(v int) int {
