func (rt *RateTable) resolveRate(date, currency string, maxStaleness int) (float64, int, string) {
  if !rt.known[currency] {
    return 0, 0, "fx_unknown_currency"
  }
  if m, ok := rt.days[date]; ok {
    if r, ok := m[currency]; ok {
      if isUsableRate(r) {
        return r, 0, ""
      }
      return 0, 0, "bad_rate"
    }
  }
  if maxStaleness > 0 {
    eventDay := dayEpoch(date)
    if !eventDay.IsZero() {
      var bestDate string
      var bestDist int64 = -1
      for _, d := range sortedKeys(rt.days) {
        if _, ok := rt.days[d][currency]; !ok {
          continue
        }
        dayTime := dayEpoch(d)
        if dayTime.IsZero() {
          continue
        }
        dist := absInt64(dayTime.Unix() - eventDay.Unix())
        if dist > int64(maxStaleness) {
          continue
        }
        if bestDist < 0 || dist < bestDist || (dist == bestDist && d < bestDate) {
          bestDist = dist
          bestDate = d
        }
