      if bestDate != "" {
        r := rt.days[bestDate][currency]
        if isUsableRate(r) {
          return r, calendarDayDiff(bestDate, date), ""
        }
        return 0, 0, "bad_rate"
      }
    }
  }
  return 0, 0, "missing_rate"
}

